#!/usr/bin/env python3
"""QuickJS-like JavaScript interpreter (minimal subset)."""
from __future__ import annotations
import sys
import os
import math
import re
import json as _json

VERSION = "2025-09-13"

# ============================================================================
# Lexer
# ============================================================================

KEYWORDS = {
    'var', 'let', 'const', 'function', 'return', 'if', 'else', 'while', 'do',
    'for', 'in', 'of', 'break', 'continue', 'true', 'false', 'null', 'undefined',
    'new', 'delete', 'typeof', 'instanceof', 'void', 'this', 'try', 'catch',
    'finally', 'throw', 'switch', 'case', 'default', 'class', 'extends', 'super',
    'yield', 'async', 'await', 'static', 'get', 'set', 'import', 'export', 'from', 'as',
}

PUNCTS = [
    '>>>=', '...', '===', '!==', '**=', '>>>', '<<=', '>>=', '&&=', '||=', '??=',
    '==', '!=', '<=', '>=', '&&', '||', '??', '**', '<<', '>>', '++', '--',
    '+=', '-=', '*=', '/=', '%=', '&=', '|=', '^=', '=>',
    '?.',
    '(', ')', '{', '}', '[', ']', ',', ';', ':', '.', '?',
    '+', '-', '*', '/', '%', '&', '|', '^', '~', '!', '=', '<', '>',
]

class Token:
    __slots__ = ('type', 'value', 'line', 'col', 'after_nl')
    def __init__(self, type, value, line=0, col=0, after_nl=False):
        self.type = type
        self.value = value
        self.line = line
        self.col = col
        self.after_nl = after_nl
    def __repr__(self):
        return f"Token({self.type!r}, {self.value!r})"

class LexError(Exception):
    pass

class Lexer:
    def __init__(self, src, filename="<input>"):
        self.src = src
        self.pos = 0
        self.line = 1
        self.col = 1
        self.filename = filename
        self.tokens = []
        self.after_nl = False

    def error(self, msg):
        raise LexError(f"{self.filename}:{self.line}:{self.col}: {msg}")

    def peek(self, n=0):
        p = self.pos + n
        if p >= len(self.src):
            return ''
        return self.src[p]

    def advance(self):
        c = self.src[self.pos]
        self.pos += 1
        if c == '\n':
            self.line += 1
            self.col = 1
        else:
            self.col += 1
        return c

    def skip_ws(self):
        while self.pos < len(self.src):
            c = self.src[self.pos]
            if c in ' \t\r':
                self.advance()
            elif c == '\n':
                self.after_nl = True
                self.advance()
            elif c == '/' and self.peek(1) == '/':
                while self.pos < len(self.src) and self.src[self.pos] != '\n':
                    self.advance()
            elif c == '/' and self.peek(1) == '*':
                self.advance(); self.advance()
                while self.pos < len(self.src):
                    if self.src[self.pos] == '*' and self.peek(1) == '/':
                        self.advance(); self.advance()
                        break
                    if self.src[self.pos] == '\n':
                        self.after_nl = True
                    self.advance()
            elif c == '#' and self.peek(1) == '!' and self.pos == 0:
                while self.pos < len(self.src) and self.src[self.pos] != '\n':
                    self.advance()
            else:
                break

    def read_string(self, quote):
        start_line = self.line
        start_col = self.col
        self.advance()  # opening quote
        result = []
        while self.pos < len(self.src) and self.src[self.pos] != quote:
            c = self.src[self.pos]
            if c == '\\':
                self.advance()
                if self.pos >= len(self.src):
                    self.error("unterminated string")
                e = self.advance()
                if e == 'n': result.append('\n')
                elif e == 't': result.append('\t')
                elif e == 'r': result.append('\r')
                elif e == '\\': result.append('\\')
                elif e == "'": result.append("'")
                elif e == '"': result.append('"')
                elif e == '`': result.append('`')
                elif e == '0': result.append('\0')
                elif e == 'b': result.append('\b')
                elif e == 'f': result.append('\f')
                elif e == 'v': result.append('\v')
                elif e == '\n': pass  # line continuation
                elif e == 'x':
                    h = self.src[self.pos:self.pos+2]
                    if len(h) < 2 or not all(ch in '0123456789abcdefABCDEF' for ch in h):
                        self.error("invalid hex escape")
                    self.advance(); self.advance()
                    result.append(chr(int(h, 16)))
                elif e == 'u':
                    if self.peek() == '{':
                        self.advance()
                        h = ''
                        while self.pos < len(self.src) and self.src[self.pos] != '}':
                            h += self.advance()
                        if self.pos >= len(self.src):
                            self.error("unterminated unicode escape")
                        self.advance()
                        result.append(chr(int(h, 16)))
                    else:
                        h = self.src[self.pos:self.pos+4]
                        if len(h) < 4:
                            self.error("invalid unicode escape")
                        for _ in range(4):
                            self.advance()
                        result.append(chr(int(h, 16)))
                else:
                    result.append(e)
            elif c == '\n':
                self.error("unterminated string")
            else:
                result.append(c)
                self.advance()
        if self.pos >= len(self.src):
            self.error("unterminated string")
        self.advance()  # closing quote
        return Token('string', ''.join(result), start_line, start_col, self.after_nl)

    def read_template(self):
        start_line = self.line
        start_col = self.col
        self.advance()  # `
        parts = []  # list of ('str', s) or ('expr', [tokens])
        cur = []
        while self.pos < len(self.src) and self.src[self.pos] != '`':
            c = self.src[self.pos]
            if c == '\\':
                self.advance()
                e = self.advance()
                if e == 'n': cur.append('\n')
                elif e == 't': cur.append('\t')
                elif e == 'r': cur.append('\r')
                elif e == '\\': cur.append('\\')
                elif e == '`': cur.append('`')
                elif e == '$': cur.append('$')
                elif e == "'": cur.append("'")
                elif e == '"': cur.append('"')
                elif e == 'x':
                    h = self.src[self.pos:self.pos+2]
                    self.advance(); self.advance()
                    cur.append(chr(int(h,16)))
                elif e == 'u':
                    if self.peek() == '{':
                        self.advance()
                        h = ''
                        while self.pos < len(self.src) and self.src[self.pos] != '}':
                            h += self.advance()
                        self.advance()
                        cur.append(chr(int(h,16)))
                    else:
                        h = self.src[self.pos:self.pos+4]
                        for _ in range(4):
                            self.advance()
                        cur.append(chr(int(h,16)))
                else:
                    cur.append(e)
            elif c == '$' and self.peek(1) == '{':
                parts.append(('str', ''.join(cur)))
                cur = []
                self.advance(); self.advance()
                # Tokenize expression up to matching }
                depth = 1
                expr_src_start = self.pos
                while self.pos < len(self.src) and depth > 0:
                    cc = self.src[self.pos]
                    if cc == '{':
                        depth += 1
                        self.advance()
                    elif cc == '}':
                        depth -= 1
                        if depth == 0:
                            break
                        self.advance()
                    elif cc == '"' or cc == "'":
                        self.read_string(cc)
                    elif cc == '`':
                        self.read_template()
                    else:
                        self.advance()
                expr_src = self.src[expr_src_start:self.pos]
                self.advance()  # }
                # Tokenize expression separately
                sub_lex = Lexer(expr_src, self.filename)
                sub_tokens = sub_lex.tokenize()
                parts.append(('expr', sub_tokens))
            else:
                cur.append(c)
                self.advance()
        if self.pos >= len(self.src):
            self.error("unterminated template")
        parts.append(('str', ''.join(cur)))
        self.advance()  # `
        return Token('template', parts, start_line, start_col, self.after_nl)

    def read_number(self):
        start_line = self.line
        start_col = self.col
        start = self.pos
        if self.src[self.pos] == '0' and self.peek(1) in 'xX':
            self.advance(); self.advance()
            while self.pos < len(self.src) and self.src[self.pos] in '0123456789abcdefABCDEF_':
                self.advance()
            s = self.src[start:self.pos].replace('_', '')
            if self.peek() == 'n':
                self.advance()
                return Token('bigint', int(s, 16), start_line, start_col, self.after_nl)
            return Token('number', float(int(s, 16)), start_line, start_col, self.after_nl)
        if self.src[self.pos] == '0' and self.peek(1) in 'oO':
            self.advance(); self.advance()
            while self.pos < len(self.src) and self.src[self.pos] in '01234567_':
                self.advance()
            s = self.src[start:self.pos].replace('_', '')
            if self.peek() == 'n':
                self.advance()
                return Token('bigint', int(s, 8), start_line, start_col, self.after_nl)
            return Token('number', float(int(s, 8)), start_line, start_col, self.after_nl)
        if self.src[self.pos] == '0' and self.peek(1) in 'bB':
            self.advance(); self.advance()
            while self.pos < len(self.src) and self.src[self.pos] in '01_':
                self.advance()
            s = self.src[start:self.pos].replace('_', '')
            if self.peek() == 'n':
                self.advance()
                return Token('bigint', int(s, 2), start_line, start_col, self.after_nl)
            return Token('number', float(int(s, 2)), start_line, start_col, self.after_nl)
        while self.pos < len(self.src) and (self.src[self.pos].isdigit() or self.src[self.pos] == '_'):
            self.advance()
        is_float = False
        if self.peek() == '.' and self.src[self.pos+1:self.pos+2].isdigit():
            is_float = True
            self.advance()
            while self.pos < len(self.src) and (self.src[self.pos].isdigit() or self.src[self.pos] == '_'):
                self.advance()
        elif self.peek() == '.' and not (self.src[self.pos+1:self.pos+2].isalpha() or self.src[self.pos+1:self.pos+2] == '_'):
            is_float = True
            self.advance()
            while self.pos < len(self.src) and (self.src[self.pos].isdigit() or self.src[self.pos] == '_'):
                self.advance()
        if self.peek() in 'eE':
            is_float = True
            self.advance()
            if self.peek() in '+-':
                self.advance()
            while self.pos < len(self.src) and self.src[self.pos].isdigit():
                self.advance()
        s = self.src[start:self.pos].replace('_', '')
        if not is_float and self.peek() == 'n':
            self.advance()
            return Token('bigint', int(s), start_line, start_col, self.after_nl)
        if is_float:
            return Token('number', float(s), start_line, start_col, self.after_nl)
        return Token('number', float(int(s)), start_line, start_col, self.after_nl)

    def read_ident(self):
        start_line = self.line
        start_col = self.col
        start = self.pos
        while self.pos < len(self.src) and (self.src[self.pos].isalnum() or self.src[self.pos] == '_' or self.src[self.pos] == '$'):
            self.advance()
        word = self.src[start:self.pos]
        if word in KEYWORDS:
            return Token(word, word, start_line, start_col, self.after_nl)
        return Token('ident', word, start_line, start_col, self.after_nl)

    def can_regex(self):
        # Simple heuristic: regex can follow operators or certain keywords
        for t in reversed(self.tokens):
            if t.type in ('number', 'string', 'ident', 'template', 'bigint',
                          'this', 'true', 'false', 'null', 'undefined',
                          ')', ']'):
                return False
            return True
        return True

    def read_regex(self):
        start_line = self.line
        start_col = self.col
        start = self.pos
        self.advance()  # /
        in_class = False
        while self.pos < len(self.src):
            c = self.src[self.pos]
            if c == '\\':
                self.advance()
                if self.pos < len(self.src):
                    self.advance()
                continue
            if c == '[':
                in_class = True
            elif c == ']':
                in_class = False
            elif c == '/' and not in_class:
                self.advance()
                break
            elif c == '\n':
                self.error("unterminated regex")
            self.advance()
        # flags
        flags_start = self.pos
        while self.pos < len(self.src) and self.src[self.pos].isalpha():
            self.advance()
        body = self.src[start+1:flags_start-1]
        flags = self.src[flags_start:self.pos]
        return Token('regex', (body, flags), start_line, start_col, self.after_nl)

    def tokenize(self):
        while True:
            self.after_nl = False
            self.skip_ws()
            if self.pos >= len(self.src):
                break
            c = self.src[self.pos]
            line, col = self.line, self.col
            if c == '"' or c == "'":
                self.tokens.append(self.read_string(c))
            elif c == '`':
                self.tokens.append(self.read_template())
            elif c.isdigit():
                self.tokens.append(self.read_number())
            elif c == '.' and self.peek(1).isdigit():
                self.tokens.append(self.read_number())
            elif c.isalpha() or c == '_' or c == '$':
                self.tokens.append(self.read_ident())
            elif c == '/' and self.can_regex():
                self.tokens.append(self.read_regex())
            else:
                matched = None
                for p in PUNCTS:
                    if self.src[self.pos:self.pos+len(p)] == p:
                        matched = p
                        break
                if not matched:
                    self.error(f"unexpected character: {c!r}")
                for _ in range(len(matched)):
                    self.advance()
                self.tokens.append(Token(matched, matched, line, col, self.after_nl))
        self.tokens.append(Token('EOF', None, self.line, self.col, self.after_nl))
        return self.tokens
