# ============================================================================
# Parser
# ============================================================================

class ParseError(Exception):
    def __init__(self, msg, line=0, col=0):
        super().__init__(msg)
        self.line = line
        self.col = col

class Node:
    def __init__(self, type, **kwargs):
        self.type = type
        self.__dict__.update(kwargs)
    def __repr__(self):
        return f"Node({self.type}, {self.__dict__})"

# Precedence levels for binary operators (higher binds tighter)
# We'll use a Pratt parser style
BIN_PREC = {
    '||': 3, '??': 3,
    '&&': 4,
    '|': 5,
    '^': 6,
    '&': 7,
    '==': 8, '!=': 8, '===': 8, '!==': 8,
    '<': 9, '>': 9, '<=': 9, '>=': 9, 'instanceof': 9, 'in': 9,
    '<<': 10, '>>': 10, '>>>': 10,
    '+': 11, '-': 11,
    '*': 12, '/': 12, '%': 12,
    '**': 13,
}
RIGHT_ASSOC = {'**'}
ASSIGN_OPS = {'=', '+=', '-=', '*=', '/=', '%=', '**=', '&=', '|=', '^=',
              '<<=', '>>=', '>>>=', '&&=', '||=', '??='}

class Parser:
    def __init__(self, tokens, filename="<input>"):
        self.toks = tokens
        self.pos = 0
        self.filename = filename

    def peek(self, n=0):
        return self.toks[self.pos + n]

    def next(self):
        t = self.toks[self.pos]
        self.pos += 1
        return t

    def match(self, *types):
        if self.peek().type in types:
            return self.next()
        return None

    def expect(self, type, msg=None):
        t = self.peek()
        if t.type != type:
            raise ParseError(f"expected {type!r}, got {t.type!r} ({t.value!r})", t.line, t.col)
        return self.next()

    def parse_program(self):
        body = []
        while self.peek().type != 'EOF':
            body.append(self.parse_statement())
        return Node('Program', body=body)

    def parse_statement(self):
        t = self.peek()
        tt = t.type
        if tt == '{':
            return self.parse_block()
        if tt == ';':
            self.next()
            return Node('Empty')
        if tt == 'var' or tt == 'let' or tt == 'const':
            return self.parse_var_decl()
        if tt == 'if':
            return self.parse_if()
        if tt == 'while':
            return self.parse_while()
        if tt == 'do':
            return self.parse_do_while()
        if tt == 'for':
            return self.parse_for()
        if tt == 'return':
            return self.parse_return()
        if tt == 'break':
            self.next()
            self.consume_semi()
            return Node('Break')
        if tt == 'continue':
            self.next()
            self.consume_semi()
            return Node('Continue')
        if tt == 'function':
            return self.parse_function_decl()
        if tt == 'class':
            return self.parse_class_decl()
        if tt == 'try':
            return self.parse_try()
        if tt == 'throw':
            self.next()
            arg = self.parse_expression()
            self.consume_semi()
            return Node('Throw', arg=arg)
        if tt == 'switch':
            return self.parse_switch()
        if tt == 'async' and self.peek(1).type == 'function':
            return self.parse_function_decl(is_async=True)
        # Expression statement
        expr = self.parse_expression()
        self.consume_semi()
        return Node('ExprStmt', expr=expr)

    def consume_semi(self):
        if self.peek().type == ';':
            self.next()
        # ASI: newline or end-of-block/file
        # We're lenient

    def parse_block(self):
        self.expect('{')
        body = []
        while self.peek().type != '}' and self.peek().type != 'EOF':
            body.append(self.parse_statement())
        self.expect('}')
        return Node('Block', body=body)

    def parse_var_decl(self):
        kind = self.next().value
        decls = []
        while True:
            target = self.parse_binding_target()
            init = None
            if self.match('='):
                init = self.parse_assignment()
            decls.append((target, init))
            if not self.match(','):
                break
        self.consume_semi()
        return Node('VarDecl', kind=kind, decls=decls)

    def parse_binding_target(self):
        t = self.peek()
        if t.type == '[':
            return self.parse_array_pattern()
        if t.type == '{':
            return self.parse_object_pattern()
        if t.type == 'ident':
            return Node('Ident', name=self.next().value)
        raise ParseError(f"expected binding target, got {t.type}", t.line, t.col)

    def parse_array_pattern(self):
        self.expect('[')
        elems = []
        while self.peek().type != ']':
            if self.match(','):
                elems.append(None)
                continue
            if self.match('...'):
                rest = self.parse_binding_target()
                elems.append(Node('RestElement', arg=rest))
                break
            target = self.parse_binding_target()
            default = None
            if self.match('='):
                default = self.parse_assignment()
            elems.append(Node('BindingElement', target=target, default=default))
            if self.peek().type != ']':
                self.expect(',')
        self.expect(']')
        return Node('ArrayPattern', elements=elems)

    def parse_object_pattern(self):
        self.expect('{')
        props = []
        while self.peek().type != '}':
            if self.match('...'):
                rest = self.parse_binding_target()
                props.append(Node('RestElement', arg=rest))
                break
            computed = False
            if self.peek().type == '[':
                self.next()
                key = self.parse_assignment()
                self.expect(']')
                computed = True
            else:
                k = self.next()
                if k.type == 'ident' or k.type in KEYWORDS:
                    key = Node('Ident', name=k.value)
                elif k.type == 'string':
                    key = Node('Literal', value=k.value)
                elif k.type == 'number':
                    key = Node('Literal', value=k.value)
                else:
                    raise ParseError(f"bad prop key {k.type}", k.line, k.col)
            if self.match(':'):
                target = self.parse_binding_target()
            else:
                if computed:
                    raise ParseError("missing value", 0, 0)
                target = Node('Ident', name=key.name)
            default = None
            if self.match('='):
                default = self.parse_assignment()
            props.append(Node('BindingProp', key=key, computed=computed, target=target, default=default))
            if self.peek().type != '}':
                self.expect(',')
        self.expect('}')
        return Node('ObjectPattern', properties=props)

    def parse_if(self):
        self.expect('if')
        self.expect('(')
        test = self.parse_expression()
        self.expect(')')
        cons = self.parse_statement()
        alt = None
        if self.match('else'):
            alt = self.parse_statement()
        return Node('If', test=test, cons=cons, alt=alt)

    def parse_while(self):
        self.expect('while')
        self.expect('(')
        test = self.parse_expression()
        self.expect(')')
        body = self.parse_statement()
        return Node('While', test=test, body=body)

    def parse_do_while(self):
        self.expect('do')
        body = self.parse_statement()
        self.expect('while')
        self.expect('(')
        test = self.parse_expression()
        self.expect(')')
        self.consume_semi()
        return Node('DoWhile', body=body, test=test)

    def parse_for(self):
        self.expect('for')
        self.expect('(')
        init = None
        if self.peek().type == ';':
            init = None
        elif self.peek().type in ('var', 'let', 'const'):
            kind = self.next().value
            target = self.parse_binding_target()
            if self.peek().type == 'in':
                self.next()
                right = self.parse_expression()
                self.expect(')')
                body = self.parse_statement()
                return Node('ForIn', kind=kind, target=target, right=right, body=body)
            if self.peek().type == 'of':
                self.next()
                right = self.parse_assignment()
                self.expect(')')
                body = self.parse_statement()
                return Node('ForOf', kind=kind, target=target, right=right, body=body)
            decls = []
            init_val = None
            if self.match('='):
                init_val = self.parse_assignment()
            decls.append((target, init_val))
            while self.match(','):
                t2 = self.parse_binding_target()
                iv = None
                if self.match('='):
                    iv = self.parse_assignment()
                decls.append((t2, iv))
            init = Node('VarDecl', kind=kind, decls=decls)
        else:
            expr = self.parse_expression(no_in=True)
            if self.peek().type == 'in':
                self.next()
                right = self.parse_expression()
                self.expect(')')
                body = self.parse_statement()
                return Node('ForIn', kind=None, target=expr, right=right, body=body)
            if self.peek().type == 'of':
                self.next()
                right = self.parse_assignment()
                self.expect(')')
                body = self.parse_statement()
                return Node('ForOf', kind=None, target=expr, right=right, body=body)
            init = Node('ExprStmt', expr=expr)
        self.expect(';')
        test = None
        if self.peek().type != ';':
            test = self.parse_expression()
        self.expect(';')
        update = None
        if self.peek().type != ')':
            update = self.parse_expression()
        self.expect(')')
        body = self.parse_statement()
        return Node('For', init=init, test=test, update=update, body=body)

    def parse_return(self):
        tok = self.expect('return')
        arg = None
        if self.peek().type not in (';', '}', 'EOF') and not self.peek().after_nl:
            arg = self.parse_expression()
        self.consume_semi()
        return Node('Return', arg=arg)

    def parse_function_decl(self, is_async=False):
        if is_async:
            self.next()  # async
        self.expect('function')
        is_gen = bool(self.match('*'))
        name = None
        if self.peek().type == 'ident':
            name = self.next().value
        params = self.parse_params()
        body = self.parse_block()
        return Node('FunctionDecl', name=name, params=params, body=body, is_async=is_async, is_generator=is_gen)

    def parse_params(self):
        self.expect('(')
        params = []
        while self.peek().type != ')':
            if self.match('...'):
                target = self.parse_binding_target()
                params.append(Node('RestParam', target=target))
                break
            target = self.parse_binding_target()
            default = None
            if self.match('='):
                default = self.parse_assignment()
            params.append(Node('Param', target=target, default=default))
            if self.peek().type != ')':
                self.expect(',')
        self.expect(')')
        return params

    def parse_class_decl(self, is_expr=False):
        self.expect('class')
        name = None
        if self.peek().type == 'ident':
            name = self.next().value
        superclass = None
        if self.match('extends'):
            superclass = self.parse_left_hand_side()
        self.expect('{')
        methods = []
        while self.peek().type != '}':
            if self.match(';'):
                continue
            is_static = False
            if self.peek().type == 'static' and self.peek(1).type not in ('(', '=', ';'):
                self.next()
                is_static = True
            kind = 'method'
            t = self.peek()
            if t.type == 'get' and self.peek(1).type != '(':
                self.next(); kind = 'get'
            elif t.type == 'set' and self.peek(1).type != '(':
                self.next(); kind = 'set'
            # method name
            k = self.peek()
            if k.type == 'ident' or k.type in KEYWORDS:
                method_name = self.next().value
            elif k.type == 'string':
                method_name = self.next().value
            elif k.type == 'number':
                method_name = str(self.next().value)
            else:
                raise ParseError(f"bad class member name {k.type}", k.line, k.col)
            # field or method
            if self.peek().type == '(':
                params = self.parse_params()
                body = self.parse_block()
                methods.append(Node('Method', name=method_name, kind=kind, static=is_static, params=params, body=body))
            else:
                # class field
                init = None
                if self.match('='):
                    init = self.parse_assignment()
                self.consume_semi()
                methods.append(Node('Field', name=method_name, static=is_static, init=init))
        self.expect('}')
        n = Node('Class', name=name, superclass=superclass, body=methods)
        if is_expr:
            return n
        return Node('ClassDecl', cls=n)

    def parse_try(self):
        self.expect('try')
        block = self.parse_block()
        handler = None
        finalizer = None
        if self.match('catch'):
            param = None
            if self.match('('):
                param = self.parse_binding_target()
                self.expect(')')
            body = self.parse_block()
            handler = Node('Catch', param=param, body=body)
        if self.match('finally'):
            finalizer = self.parse_block()
        return Node('Try', block=block, handler=handler, finalizer=finalizer)

    def parse_switch(self):
        self.expect('switch')
        self.expect('(')
        disc = self.parse_expression()
        self.expect(')')
        self.expect('{')
        cases = []
        while self.peek().type != '}':
            if self.match('case'):
                test = self.parse_expression()
                self.expect(':')
                stmts = []
                while self.peek().type not in ('case', 'default', '}'):
                    stmts.append(self.parse_statement())
                cases.append(Node('Case', test=test, body=stmts))
            elif self.match('default'):
                self.expect(':')
                stmts = []
                while self.peek().type not in ('case', 'default', '}'):
                    stmts.append(self.parse_statement())
                cases.append(Node('Case', test=None, body=stmts))
            else:
                t = self.peek()
                raise ParseError(f"expected case/default got {t.type}", t.line, t.col)
        self.expect('}')
        return Node('Switch', disc=disc, cases=cases)

    def parse_expression(self, no_in=False):
        expr = self.parse_assignment(no_in=no_in)
        while self.match(','):
            right = self.parse_assignment(no_in=no_in)
            expr = Node('Sequence', exprs=[expr, right]) if expr.type != 'Sequence' else Node('Sequence', exprs=expr.exprs + [right])
        return expr

    def parse_assignment(self, no_in=False):
        # Check arrow function start
        if self.is_arrow_start():
            return self.parse_arrow_function()
        expr = self.parse_conditional(no_in=no_in)
        if self.peek().type in ASSIGN_OPS:
            op = self.next().type
            right = self.parse_assignment(no_in=no_in)
            return Node('Assign', op=op, left=expr, right=right)
        return expr

    def is_arrow_start(self):
        # (params) => ...   OR   ident => ...   OR   async ident => ...  OR  async (...)=>
        if self.peek().type == 'ident' and self.peek(1).type == '=>':
            return True
        if self.peek().type == 'async' and self.peek(1).type == 'ident' and self.peek(2).type == '=>':
            return True
        start = self.pos
        # Try scanning (....) =>
        if self.peek().type == '(' or (self.peek().type == 'async' and self.peek(1).type == '('):
            if self.peek().type == 'async':
                self.pos += 1
            if self.peek().type != '(':
                self.pos = start
                return False
            depth = 0
            p = self.pos
            while p < len(self.toks):
                t = self.toks[p]
                if t.type == '(':
                    depth += 1
                elif t.type == ')':
                    depth -= 1
                    if depth == 0:
                        if p+1 < len(self.toks) and self.toks[p+1].type == '=>':
                            self.pos = start
                            return True
                        self.pos = start
                        return False
                elif t.type == 'EOF':
                    break
                p += 1
        self.pos = start
        return False

    def parse_arrow_function(self):
        is_async = False
        if self.peek().type == 'async':
            self.next()
            is_async = True
        params = []
        if self.peek().type == 'ident':
            params.append(Node('Param', target=Node('Ident', name=self.next().value), default=None))
        else:
            params = self.parse_params()
        self.expect('=>')
        if self.peek().type == '{':
            body = self.parse_block()
            return Node('Arrow', params=params, body=body, is_expr=False, is_async=is_async)
        expr = self.parse_assignment()
        return Node('Arrow', params=params, body=expr, is_expr=True, is_async=is_async)

    def parse_conditional(self, no_in=False):
        test = self.parse_binary(0, no_in=no_in)
        if self.match('?'):
            cons = self.parse_assignment()
            self.expect(':')
            alt = self.parse_assignment(no_in=no_in)
            return Node('Conditional', test=test, cons=cons, alt=alt)
        return test

    def parse_binary(self, min_prec, no_in=False):
        left = self.parse_unary()
        while True:
            t = self.peek()
            op = t.type
            if op == 'in' and no_in:
                break
            if op not in BIN_PREC:
                break
            prec = BIN_PREC[op]
            if prec < min_prec:
                break
            self.next()
            next_min = prec + (0 if op in RIGHT_ASSOC else 1)
            right = self.parse_binary(next_min, no_in=no_in)
            left = Node('Binary', op=op, left=left, right=right)
        return left

    def parse_unary(self):
        t = self.peek()
        if t.type in ('!', '-', '+', '~', 'typeof', 'void', 'delete'):
            self.next()
            arg = self.parse_unary()
            return Node('Unary', op=t.type, arg=arg, prefix=True)
        if t.type in ('++', '--'):
            self.next()
            arg = self.parse_unary()
            return Node('Update', op=t.type, arg=arg, prefix=True)
        if t.type == 'await':
            self.next()
            arg = self.parse_unary()
            return Node('Await', arg=arg)
        return self.parse_postfix()

    def parse_postfix(self):
        expr = self.parse_left_hand_side()
        t = self.peek()
        if t.type in ('++', '--') and not t.after_nl:
            self.next()
            return Node('Update', op=t.type, arg=expr, prefix=False)
        # ** needs higher prec than unary; handled in binary? Actually ** is fine.
        return expr

    def parse_left_hand_side(self):
        if self.peek().type == 'new':
            return self.parse_new()
        expr = self.parse_primary()
        return self.parse_calls_and_members(expr)

    def parse_new(self):
        self.expect('new')
        if self.peek().type == 'new':
            callee = self.parse_new()
        else:
            callee = self.parse_primary()
            # member access (no call)
            while True:
                t = self.peek()
                if t.type == '.':
                    self.next()
                    name = self.next().value
                    callee = Node('Member', obj=callee, prop=name, computed=False)
                elif t.type == '[':
                    self.next()
                    prop = self.parse_expression()
                    self.expect(']')
                    callee = Node('Member', obj=callee, prop=prop, computed=True)
                else:
                    break
        args = []
        if self.peek().type == '(':
            args = self.parse_arguments()
        expr = Node('New', callee=callee, args=args)
        return self.parse_calls_and_members(expr)

    def parse_calls_and_members(self, expr):
        while True:
            t = self.peek()
            if t.type == '.':
                self.next()
                nm = self.next()
                name = nm.value
                expr = Node('Member', obj=expr, prop=name, computed=False)
            elif t.type == '?.':
                self.next()
                nm = self.next()
                if nm.type == '(':
                    # optional call
                    args = []
                    while self.peek().type != ')':
                        if self.match('...'):
                            args.append(Node('Spread', arg=self.parse_assignment()))
                        else:
                            args.append(self.parse_assignment())
                        if self.peek().type != ')':
                            self.expect(',')
                    self.expect(')')
                    expr = Node('Call', callee=expr, args=args, optional=True)
                elif nm.type == '[':
                    prop = self.parse_expression()
                    self.expect(']')
                    expr = Node('Member', obj=expr, prop=prop, computed=True, optional=True)
                else:
                    expr = Node('Member', obj=expr, prop=nm.value, computed=False, optional=True)
            elif t.type == '[':
                self.next()
                prop = self.parse_expression()
                self.expect(']')
                expr = Node('Member', obj=expr, prop=prop, computed=True)
            elif t.type == '(':
                args = self.parse_arguments()
                expr = Node('Call', callee=expr, args=args)
            elif t.type == 'template':
                tag_tok = self.next()
                expr = Node('TaggedTemplate', tag=expr, quasi=tag_tok.value)
            else:
                break
        return expr

    def parse_arguments(self):
        self.expect('(')
        args = []
        while self.peek().type != ')':
