UNDEFINED = object()  # sentinel distinct from None (null)

def js_type(v):
    if v is UNDEFINED: return 'undefined'
    if v is None: return 'object'  # null
    if isinstance(v, bool): return 'boolean'
    if isinstance(v, (int, float)): return 'number'
    if isinstance(v, BigInt): return 'bigint'
    if isinstance(v, str): return 'string'
    if isinstance(v, JSFunction): return 'function'
    if isinstance(v, JSObject): return 'function' if v.is_callable() else 'object'
    if isinstance(v, JSSymbol): return 'symbol'
    return 'object'

def js_tobool(v):
    if v is UNDEFINED or v is None: return False
    if isinstance(v, bool): return v
    if isinstance(v, (int, float)):
        if v != v: return False  # NaN
        return v != 0
    if isinstance(v, BigInt): return v.v != 0
    if isinstance(v, str): return len(v) > 0
    return True

def js_tonumber(v):
    if v is UNDEFINED: return float('nan')
    if v is None: return 0.0
    if isinstance(v, bool): return 1.0 if v else 0.0
    if isinstance(v, (int, float)): return float(v)
    if isinstance(v, str):
        s = v.strip()
        if s == '': return 0.0
        try:
            if s.startswith('0x') or s.startswith('0X'):
                return float(int(s, 16))
            if s.startswith('0o') or s.startswith('0O'):
                return float(int(s, 8))
            if s.startswith('0b') or s.startswith('0B'):
                return float(int(s, 2))
            if s == 'Infinity' or s == '+Infinity': return float('inf')
            if s == '-Infinity': return float('-inf')
            return float(s)
        except Exception:
            return float('nan')
    if isinstance(v, BigInt):
        return float(v.v)
    if isinstance(v, JSObject):
        prim = to_primitive(v, 'number')
        return js_tonumber(prim)
    return float('nan')

def js_toint32(v):
    n = js_tonumber(v)
    if n != n or n in (float('inf'), float('-inf')): return 0
    n = int(n) if n >= 0 else -int(-n)
    n = n & 0xffffffff
    if n >= 0x80000000:
        n -= 0x100000000
    return n

def js_touint32(v):
    n = js_tonumber(v)
    if n != n or n in (float('inf'), float('-inf')): return 0
    n = int(n) if n >= 0 else -int(-n)
    return n & 0xffffffff

def num_to_string(n):
    # Match QuickJS / JS spec formatting
    if n != n:
        return 'NaN'
    if n == float('inf'):
        return 'Infinity'
    if n == float('-inf'):
        return '-Infinity'
    if n == 0:
        return '0'
    # integer?
    if isinstance(n, float) and n.is_integer() and abs(n) < 1e21:
        i = int(n)
        return str(i)
    # Use JS-like formatting
    # Python's repr for floats is often similar but not exact
    # Use shortest representation
    s = repr(n)
    # Python uses 'e' format when the number is small or large
    # JS uses similar thresholds: abs < 1e-6 => exponential
    if 'e' in s:
        # Normalize exponent: python uses 'e-07' while JS uses 'e-7'
        mant, exp = s.split('e')
        exp_int = int(exp)
        # strip trailing zeros in mantissa after decimal
        if '.' in mant:
            mant = mant.rstrip('0').rstrip('.')
        if exp_int >= 0:
            return f"{mant}e+{exp_int}"
        else:
            return f"{mant}e{exp_int}"
    return s

