    return str(v)

def to_primitive(v, hint='default'):
    if not isinstance(v, JSObject):
        return v
    # Try Symbol.toPrimitive? Skip. Use toString/valueOf.
    methods = ['valueOf', 'toString'] if hint == 'number' else ['toString', 'valueOf']
    if hint == 'default':
        methods = ['valueOf', 'toString']
    for m in methods:
        fn = v.get(m)
        if isinstance(fn, (JSFunction, JSNativeFunction)):
            res = call_function(fn, v, [])
            if not isinstance(res, JSObject):
