def js_eq(a, b):  # == (loose)
    if isinstance(a, bool): a = 1.0 if a else 0.0
    if isinstance(b, bool): b = 1.0 if b else 0.0
    if js_strict_eq(a, b): return True
    if a is None and b is UNDEFINED: return True
    if a is UNDEFINED and b is None: return True
    if isinstance(a, (int, float)) and isinstance(b, str):
        return js_eq(a, js_tonumber(b))
    if isinstance(a, str) and isinstance(b, (int, float)):
        return js_eq(js_tonumber(a), b)
    if isinstance(a, BigInt) and isinstance(b, (int, float)):
        if b != b or b in (float('inf'), float('-inf')): return False
        if not float(b).is_integer(): return False
        return a.v == int(b)
    if isinstance(b, BigInt) and isinstance(a, (int, float)):
        return js_eq(b, a)
    if isinstance(a, BigInt) and isinstance(b, str):
        try: return a.v == int(b)
        except: return False
    if isinstance(b, BigInt) and isinstance(a, str):
        return js_eq(b, a)
    if isinstance(a, JSObject) and isinstance(b, (int, float, str, BigInt)):
        return js_eq(to_primitive(a), b)
    if isinstance(b, JSObject) and isinstance(a, (int, float, str, BigInt)):
        return js_eq(a, to_primitive(b))
    return False

def js_strict_eq(a, b):
    if a is UNDEFINED and b is UNDEFINED: return True
    if a is None and b is None: return True
    if a is UNDEFINED or b is UNDEFINED: return False
    if a is None or b is None: return False
    ta = type(a); tb = type(b)
    if isinstance(a, bool) != isinstance(b, bool): return False
    if isinstance(a, (int, float)) and isinstance(b, (int, float)) and not isinstance(a, bool) and not isinstance(b, bool):
        if a != a or b != b: return False
        return float(a) == float(b)
    if isinstance(a, BigInt) and isinstance(b, BigInt): return a.v == b.v
    if isinstance(a, str) and isinstance(b, str): return a == b
    if isinstance(a, bool) and isinstance(b, bool): return a == b
    if isinstance(a, JSObject) and isinstance(b, JSObject): return a is b
    if isinstance(a, JSSymbol) and isinstance(b, JSSymbol): return a is b
    return False

