# ============================================================================
# Environment / scopes
# ============================================================================

class Env:
    __slots__ = ('parent', 'vars', 'consts', 'is_function_scope')
    def __init__(self, parent=None, is_function_scope=False):
        self.parent = parent
        self.vars = {}
        self.consts = set()
        self.is_function_scope = is_function_scope
    def define(self, name, value, is_const=False):
        self.vars[name] = value
        if is_const:
            self.consts.add(name)
    def define_var(self, name, value):
        # var goes to nearest function scope
        env = self
        while env.parent is not None and not env.is_function_scope:
            env = env.parent
        if name not in env.vars:
            env.vars[name] = value
    def get(self, name):
        env = self
        while env is not None:
            if name in env.vars:
                return env.vars[name]
            env = env.parent
        raise JSException(make_error('ReferenceError', f"'{name}' is not defined"))
    def has(self, name):
        env = self
        while env is not None:
            if name in env.vars:
                return True
            env = env.parent
        return False
    def set(self, name, value):
        env = self
        while env is not None:
            if name in env.vars:
                if name in env.consts:
                    raise JSException(make_error('TypeError', f"invalid assignment to const '{name}'"))
                env.vars[name] = value
                return
            env = env.parent
        # Implicit global assignment (non-strict)
        GLOBAL_ENV.vars[name] = value

# Global prototypes and global env placeholders (initialized later)
OBJECT_PROTO = None
ARRAY_PROTO = None
FUNCTION_PROTO = None
STRING_PROTO = None
NUMBER_PROTO = None
BOOLEAN_PROTO = None
ERROR_PROTO = None
GLOBAL_OBJ = None
GLOBAL_ENV = None
ERROR_CTORS = {}

def make_error(name, message):
    proto = ERROR_CTORS.get(name, {}).get('proto') if name in ERROR_CTORS else ERROR_PROTO
    if proto is None:
        proto = ERROR_PROTO
    err = JSObject(proto=proto, cls_name='Error')
    err.define_property('message', message, writable=True, enumerable=False, configurable=True)
    err.define_property('name', name, writable=True, enumerable=False, configurable=True)
    err.define_property('stack', '', writable=True, enumerable=False, configurable=True)
    return err

