class BreakSignal(Exception): pass
class ContinueSignal(Exception): pass
class ReturnSignal(Exception):
    def __init__(self, value):
        self.value = value

class Interpreter:
    def __init__(self):
        self.current_filename = '<input>'

    def run(self, node, env):
        body = node.body
        # hoist function declarations
        for stmt in body:
            if stmt.type == 'FunctionDecl':
                fn = self.make_function(stmt.name, stmt.params, stmt.body, env, is_async=stmt.is_async, is_generator=stmt.is_generator)
                env.define(stmt.name, fn)
        result = UNDEFINED
        for stmt in body:
            if stmt.type == 'FunctionDecl':
                continue
            result = self.exec_stmt(stmt, env)
        return result

    def exec_stmt(self, stmt, env):
        t = stmt.type
        if t == 'ExprStmt':
            return self.eval_expr(stmt.expr, env)
        if t == 'VarDecl':
            for target, init in stmt.decls:
                val = self.eval_expr(init, env) if init else UNDEFINED
                self.bind_pattern(target, val, env, stmt.kind)
            return UNDEFINED
        if t == 'Block':
            new_env = Env(parent=env)
            # hoist function decls
            for s in stmt.body:
                if s.type == 'FunctionDecl':
                    fn = self.make_function(s.name, s.params, s.body, new_env, is_async=s.is_async, is_generator=s.is_generator)
                    new_env.define(s.name, fn)
            for s in stmt.body:
                if s.type == 'FunctionDecl':
                    continue
                self.exec_stmt(s, new_env)
            return UNDEFINED
        if t == 'If':
            if js_tobool(self.eval_expr(stmt.test, env)):
                self.exec_stmt(stmt.cons, env)
            elif stmt.alt:
                self.exec_stmt(stmt.alt, env)
            return UNDEFINED
        if t == 'While':
            while js_tobool(self.eval_expr(stmt.test, env)):
                try:
                    self.exec_stmt(stmt.body, env)
                except BreakSignal:
                    break
                except ContinueSignal:
                    continue
            return UNDEFINED
        if t == 'DoWhile':
            while True:
                try:
                    self.exec_stmt(stmt.body, env)
                except BreakSignal:
                    break
                except ContinueSignal:
                    pass
                if not js_tobool(self.eval_expr(stmt.test, env)):
                    break
            return UNDEFINED
        if t == 'For':
            new_env = Env(parent=env)
            if stmt.init:
                self.exec_stmt(stmt.init, new_env)
            while True:
                if stmt.test and not js_tobool(self.eval_expr(stmt.test, new_env)):
                    break
                try:
                    self.exec_stmt(stmt.body, new_env)
                except BreakSignal:
                    break
                except ContinueSignal:
                    pass
                if stmt.update:
                    self.eval_expr(stmt.update, new_env)
            return UNDEFINED
        if t == 'ForIn':
            new_env = Env(parent=env)
            obj = self.eval_expr(stmt.right, new_env)
            if obj is UNDEFINED or obj is None:
                return UNDEFINED
            keys = self._for_in_keys(obj)
            for k in keys:
                self._assign_for_target(stmt, k, new_env)
                try:
                    self.exec_stmt(stmt.body, new_env)
                except BreakSignal:
                    break
                except ContinueSignal:
                    continue
            return UNDEFINED
        if t == 'ForOf':
            new_env = Env(parent=env)
            iterable = self.eval_expr(stmt.right, new_env)
            for v in self._iterate(iterable):
                self._assign_for_target(stmt, v, new_env)
                try:
                    self.exec_stmt(stmt.body, new_env)
                except BreakSignal:
                    break
                except ContinueSignal:
                    continue
            return UNDEFINED
        if t == 'Return':
            val = self.eval_expr(stmt.arg, env) if stmt.arg else UNDEFINED
            raise ReturnSignal(val)
        if t == 'Break':
            raise BreakSignal()
        if t == 'Continue':
            raise ContinueSignal()
        if t == 'Throw':
            val = self.eval_expr(stmt.arg, env)
            raise JSException(val)
        if t == 'Try':
            try:
                self.exec_stmt(stmt.block, env)
            except JSException as e:
                if stmt.handler:
                    handler_env = Env(parent=env)
                    if stmt.handler.param:
                        self.bind_pattern(stmt.handler.param, e.value, handler_env, 'let')
                    self.exec_stmt(stmt.handler.body, handler_env)
                elif not stmt.finalizer:
                    raise
                else:
                    saved_exc = e
                    self.exec_stmt(stmt.finalizer, env)
                    raise saved_exc
            if stmt.finalizer:
                self.exec_stmt(stmt.finalizer, env)
            return UNDEFINED
        if t == 'Switch':
            disc = self.eval_expr(stmt.disc, env)
            new_env = Env(parent=env)
            matched = False
            try:
                for i, case in enumerate(stmt.cases):
                    if not matched:
                        if case.test is None:
                            continue
