                        if js_strict_eq(disc, v):
                            matched = True
                    if matched:
                        for s in case.body:
                            self.exec_stmt(s, new_env)
                if not matched:
                    # find default and fall through from there
                    for i, case in enumerate(stmt.cases):
                        if case.test is None:
