        if t == 'Member':
            obj = self.eval_expr(node.obj, env)
            if getattr(node, 'optional', False) and (obj is UNDEFINED or obj is None):
                return UNDEFINED
            key = node.prop if not node.computed else js_tostring(self.eval_expr(node.prop, env))
            return obj_get(obj, key)
        if t == 'Spread':
            raise RuntimeError("spread not in call/array")
        if t == 'Await':
            v = self.eval_expr(node.arg, env)
            if isinstance(v, JSObject) and v.cls_name == 'Promise':
                return resolve_promise(v)
            return v
        raise RuntimeError(f"unknown expr: {t}")

    def eval_binary(self, node, env):
        op = node.op
        if op == '&&':
            a = self.eval_expr(node.left, env)
            if not js_tobool(a): return a
            return self.eval_expr(node.right, env)
        if op == '||':
            a = self.eval_expr(node.left, env)
            if js_tobool(a): return a
            return self.eval_expr(node.right, env)
        if op == '??':
            a = self.eval_expr(node.left, env)
            if a is UNDEFINED or a is None: return self.eval_expr(node.right, env)
            return a
        a = self.eval_expr(node.left, env)
        b = self.eval_expr(node.right, env)
        return do_binary(op, a, b)

    def eval_assign(self, node, env):
        op = node.op
        if op == '=' and node.left.type in ('ArrayPattern', 'ObjectPattern'):
            v = self.eval_expr(node.right, env)
            self.assign_pattern(node.left, v, env)
            return v
        lv = self.eval_lvalue(node.left, env)
        if op == '=':
            v = self.eval_expr(node.right, env)
            lv['set'](v)
            return v
        cur = lv['get']()
        if op == '&&=':
            if not js_tobool(cur): return cur
            v = self.eval_expr(node.right, env); lv['set'](v); return v
        if op == '||=':
            if js_tobool(cur): return cur
            v = self.eval_expr(node.right, env); lv['set'](v); return v
        if op == '??=':
            if cur is not UNDEFINED and cur is not None: return cur
            v = self.eval_expr(node.right, env); lv['set'](v); return v
        rhs = self.eval_expr(node.right, env)
        bop = op[:-1]  # strip '='
        new = do_binary(bop, cur, rhs)
        lv['set'](new)
        return new

    def assign_pattern(self, target, value, env):
        if target.type == 'ArrayPattern':
            items = list(self._iterate(value)) if value is not UNDEFINED and value is not None else []
            idx = 0
            for el in target.elements:
                if el is None:
                    idx += 1; continue
                if el.type == 'RestElement':
                    rest = JSArray(items=items[idx:], proto=ARRAY_PROTO)
                    self.assign_target(el.arg, rest, env)
                    break
                v = items[idx] if idx < len(items) else UNDEFINED
                if v is UNDEFINED and el.default:
                    v = self.eval_expr(el.default, env)
                self.assign_target(el.target, v, env) if hasattr(el, 'target') else self.assign_target(el, v, env)
                idx += 1
            return
        if target.type == 'ObjectPattern':
            seen = set()
            for p in target.properties:
                if p.type == 'RestElement':
                    rest = JSObject(proto=OBJECT_PROTO)
                    if isinstance(value, JSObject):
                        for k in value.own_enumerable_keys():
                            if k not in seen:
                                rest.set(k, value.get(k))
                    self.assign_target(p.arg, rest, env)
                    continue
                key = self._prop_key(p.key, p.computed, env)
                seen.add(key)
                v = obj_get(value, key)
                if v is UNDEFINED and p.default:
                    v = self.eval_expr(p.default, env)
                self.assign_target(p.target, v, env)
            return

    def assign_target(self, target, value, env):
        if target.type == 'Ident' or target.type == 'Identifier':
            env.set(target.name, value)
            return
        if target.type in ('ArrayPattern', 'ObjectPattern'):
            self.assign_pattern(target, value, env)
            return
        if target.type == 'Member':
            obj = self.eval_expr(target.obj, env)
            key = target.prop if not target.computed else js_tostring(self.eval_expr(target.prop, env))
            obj_set(obj, key, value)
            return
        raise RuntimeError(f"bad assign target {target.type}")

    def eval_lvalue(self, node, env):
        if node.type == 'Identifier':
            name = node.name
            return {
                'get': lambda: env.get(name),
                'set': lambda v: env.set(name, v),
            }
        if node.type == 'Member':
            obj = self.eval_expr(node.obj, env)
            key = node.prop if not node.computed else js_tostring(self.eval_expr(node.prop, env))
            return {
                'get': lambda: obj_get(obj, key),
                'set': lambda v: obj_set(obj, key, v),
            }
        raise RuntimeError(f"bad lvalue {node.type}")

    def eval_call(self, node, env):
        callee = node.callee
        this_val = UNDEFINED
        if callee.type == 'Member':
            obj = self.eval_expr(callee.obj, env)
            if getattr(callee, 'optional', False) and (obj is UNDEFINED or obj is None):
                return UNDEFINED
            key = callee.prop if not callee.computed else js_tostring(self.eval_expr(callee.prop, env))
            fn = obj_get(obj, key)
            this_val = obj
            if getattr(node, 'optional', False) and (fn is UNDEFINED or fn is None):
                return UNDEFINED
            if fn is UNDEFINED:
                raise JSException(make_error('TypeError', f"not a function: {key}"))
        elif callee.type == 'Super':
            # super(...args)
            # Find enclosing class
            e = env
            while e is not None:
                if 'super_ctor' in e.vars:
                    break
                e = e.parent
            if e is None:
                raise JSException(make_error('SyntaxError', 'super not allowed'))
            super_ctor = e.vars['super_ctor']
            this_obj = e.vars.get('this', UNDEFINED)
            args = self._eval_args(node.args, env)
            # Call super ctor with this_obj as this
            call_function(super_ctor, this_obj, args, construct=True, new_target=e.vars.get('new_target'))
            return UNDEFINED
        else:
            fn = self.eval_expr(callee, env)
            if getattr(node, 'optional', False) and (fn is UNDEFINED or fn is None):
                return UNDEFINED
        args = self._eval_args(node.args, env)
        if not (isinstance(fn, (JSFunction, JSNativeFunction, JSBoundFunction)) or (isinstance(fn, JSObject) and fn._callable)):
            raise JSException(make_error('TypeError', f"not a function"))
        return call_function(fn, this_val, args)

    def eval_new(self, node, env):
        callee = self.eval_expr(node.callee, env)
        args = self._eval_args(node.args, env)
        if not (isinstance(callee, (JSFunction, JSNativeFunction, JSBoundFunction)) or (isinstance(callee, JSObject) and callee._callable)):
            raise JSException(make_error('TypeError', 'not a constructor'))
        return construct_function(callee, args)

    def _eval_args(self, args, env):
        result = []
        for a in args:
            if a.type == 'Spread':
                v = self.eval_expr(a.arg, env)
                for x in self._iterate(v):
                    result.append(x)
            else:
                result.append(self.eval_expr(a, env))
        return result

    def make_function(self, name, params, body, env, is_arrow=False, is_async=False, is_generator=False, is_expr=False):
        fn = JSFunction(name or '', params, body, env, is_arrow=is_arrow, is_async=is_async, is_generator=is_generator, proto=FUNCTION_PROTO)
        fn._is_expr = is_expr  # for arrow expression body
        return fn

    def make_class(self, node, env):
        super_val = None
        if node.superclass:
            super_val = self.eval_expr(node.superclass, env)
        # ctor
        ctor = None
        for m in node.body:
            if m.type == 'Method' and m.name == 'constructor' and not m.static:
                ctor = m
                break
        if ctor:
            fn = self.make_function(node.name or '', ctor.params, ctor.body, env)
        else:
            # default constructor
            if super_val:
                # constructor(...args){ super(...args); }
                default_body = Node('Block', body=[
                    Node('ExprStmt', expr=Node('Call', callee=Node('Super'), args=[Node('Spread', arg=Node('Identifier', name='__args__'))]))
                ])
                params = [Node('RestParam', target=Node('Ident', name='__args__'))]
                fn = self.make_function(node.name or '', params, default_body, env)
            else:
                fn = self.make_function(node.name or '', [], Node('Block', body=[]), env)
        # Set up super chain
        if super_val:
            fn.proto = super_val
            super_proto = super_val.get('prototype') if isinstance(super_val, JSObject) else None
            if isinstance(super_proto, JSObject):
                fn.get('prototype').proto = super_proto
        fn.cls_name = 'Function'
        fn.define_property('name', node.name or '', writable=False, enumerable=False, configurable=True)
        # methods
        proto_obj = fn.get('prototype')
        for m in node.body:
            if m.type == 'Method' and m.name != 'constructor':
                mfn = self.make_function(m.name, m.params, m.body, env, is_async=False)
                mfn.home_class = fn
                target = fn if m.static else proto_obj
                if m.kind == 'get':
                    existing = target.props.get(m.name)
                    setter = existing[1][1] if isinstance(existing, tuple) and len(existing)==2 and existing[0]=='accessor' else None
                    target.define_accessor(m.name, mfn, setter)
                elif m.kind == 'set':
                    existing = target.props.get(m.name)
                    getter = existing[1][0] if isinstance(existing, tuple) and len(existing)==2 and existing[0]=='accessor' else None
                    target.define_accessor(m.name, getter, mfn)
                else:
                    target.define_property(m.name, mfn, writable=True, enumerable=False, configurable=True)
            elif m.type == 'Field' and m.static:
                val = self.eval_expr(m.init, env) if m.init else UNDEFINED
                fn.define_property(m.name, val, writable=True, enumerable=True, configurable=True)
        # Remember fields to init in constructor
        fn._instance_fields = [m for m in node.body if m.type == 'Field' and not m.static]
        fn._super_val = super_val
        fn._construct = True
        return fn

INTERP = None

def obj_get(obj, key):
    key = str(key) if not isinstance(key, str) else key
    if obj is UNDEFINED or obj is None:
        raise JSException(make_error('TypeError', f"cannot read property '{key}' of {'undefined' if obj is UNDEFINED else 'null'}"))
    if isinstance(obj, str):
        if key == 'length':
            return float(len(obj))
        if key.isdigit():
            i = int(key)
            return obj[i] if 0 <= i < len(obj) else UNDEFINED
        if STRING_PROTO is not None:
            v = STRING_PROTO.get(key)
            return v
        return UNDEFINED
    if isinstance(obj, (int, float)) and not isinstance(obj, bool):
        if NUMBER_PROTO is not None:
            return NUMBER_PROTO.get(key)
        return UNDEFINED
    if isinstance(obj, bool):
        if BOOLEAN_PROTO is not None:
            return BOOLEAN_PROTO.get(key)
        return UNDEFINED
    if isinstance(obj, BigInt):
        return UNDEFINED
    if isinstance(obj, JSObject):
        return obj.get(key)
    return UNDEFINED

def obj_set(obj, key, value):
    key = str(key) if not isinstance(key, str) else key
    if isinstance(obj, JSObject):
        obj.set(key, value)
        return
    # Silent ignore on primitives (non-strict)

def call_function(fn, this_val, args, construct=False, new_target=None):
    if isinstance(fn, JSNativeFunction):
        return fn.fn(this_val, args)
    if isinstance(fn, JSBoundFunction):
        return call_function(fn.target, fn.bound_this, fn.bound_args + args, construct=construct, new_target=new_target)
    if isinstance(fn, JSFunction):
        return invoke_js_function(fn, this_val, args, construct=construct, new_target=new_target)
    if isinstance(fn, JSObject) and fn._callable and hasattr(fn, 'fn'):
        return fn.fn(this_val, args)
    raise JSException(make_error('TypeError', 'not callable'))

def construct_function(fn, args):
    if isinstance(fn, JSNativeFunction):
        # Some natives can construct
        if fn._construct:
            return fn.fn(UNDEFINED, args)  # let the native handle construction
        raise JSException(make_error('TypeError', f'not a constructor: {fn.name}'))
    if isinstance(fn, JSBoundFunction):
        return construct_function(fn.target, fn.bound_args + args)
    if isinstance(fn, JSFunction):
        proto = fn.get('prototype')
        if not isinstance(proto, JSObject):
            proto = OBJECT_PROTO
        obj = JSObject(proto=proto)
        # run instance fields
        for field in getattr(fn, '_instance_fields', []):
            val = INTERP.eval_expr(field.init, fn.closure) if field.init else UNDEFINED
            obj.set(field.name, val)
        result = invoke_js_function(fn, obj, args, construct=True, new_target=fn)
        if isinstance(result, JSObject):
            return result
        return obj
    raise JSException(make_error('TypeError', 'not a constructor'))

def invoke_js_function(fn, this_val, args, construct=False, new_target=None):
    # Create call environment
    call_env = Env(parent=fn.closure, is_function_scope=True)
    if fn.is_arrow:
        call_env.vars['this'] = fn.this_val
    else:
        call_env.vars['this'] = this_val
    call_env.vars['arguments'] = JSArray(items=list(args), proto=ARRAY_PROTO)
    # super ctor setup
    super_val = getattr(fn, '_super_val', None)
    if super_val is not None:
        call_env.vars['super_ctor'] = super_val
        call_env.vars['new_target'] = new_target if new_target else fn
    # bind params
    i = 0
    for p in fn.params:
        if p.type == 'RestParam':
            rest = JSArray(items=list(args[i:]), proto=ARRAY_PROTO)
            INTERP.bind_pattern(p.target, rest, call_env, 'let')
            break
        val = args[i] if i < len(args) else UNDEFINED
        if val is UNDEFINED and p.default:
            val = INTERP.eval_expr(p.default, call_env)
        INTERP.bind_pattern(p.target, val, call_env, 'let')
        i += 1
    # Initialize instance fields for class (already done in construct_function on 'this')
    # execute body
    try:
        if isinstance(fn.body, Node) and fn.body.type == 'Block':
            # hoist function decls within
            for s in fn.body.body:
                if s.type == 'FunctionDecl':
                    nfn = INTERP.make_function(s.name, s.params, s.body, call_env, is_async=s.is_async, is_generator=s.is_generator)
                    call_env.define(s.name, nfn)
            for s in fn.body.body:
                if s.type == 'FunctionDecl':
                    continue
                INTERP.exec_stmt(s, call_env)
            return UNDEFINED
        else:
            # Arrow expression body
            return INTERP.eval_expr(fn.body, call_env)
    except ReturnSignal as r:
        return r.value

