def do_binary(op, a, b):
    if op == '+':
        if isinstance(a, str) or isinstance(b, str):
            if isinstance(a, JSObject): a = to_primitive(a)
            if isinstance(b, JSObject): b = to_primitive(b)
            if isinstance(a, str) or isinstance(b, str):
                return js_tostring(a) + js_tostring(b)
        if isinstance(a, JSObject): a = to_primitive(a)
        if isinstance(b, JSObject): b = to_primitive(b)
        if isinstance(a, str) or isinstance(b, str):
            return js_tostring(a) + js_tostring(b)
        if isinstance(a, BigInt) and isinstance(b, BigInt):
            return BigInt(a.v + b.v)
        return js_tonumber(a) + js_tonumber(b)
    if op == '-':
        if isinstance(a, BigInt) and isinstance(b, BigInt): return BigInt(a.v - b.v)
        return js_tonumber(a) - js_tonumber(b)
    if op == '*':
        if isinstance(a, BigInt) and isinstance(b, BigInt): return BigInt(a.v * b.v)
        return js_tonumber(a) * js_tonumber(b)
    if op == '/':
        if isinstance(a, BigInt) and isinstance(b, BigInt):
            if b.v == 0: raise JSException(make_error('RangeError', 'division by zero'))
