# Built-ins setup
# ============================================================================

def native(name, fn, length=0, construct=False):
    f = JSNativeFunction(name, fn, length=length, proto=FUNCTION_PROTO, construct=construct)
    return f

def define_method(target, name, fn, length=0):
    target.define_property(name, native(name, fn, length), writable=True, enumerable=False, configurable=True)

def setup_builtins():
    global OBJECT_PROTO, ARRAY_PROTO, FUNCTION_PROTO, STRING_PROTO, NUMBER_PROTO, BOOLEAN_PROTO, ERROR_PROTO
    global GLOBAL_OBJ, GLOBAL_ENV, ERROR_CTORS

    OBJECT_PROTO = JSObject(proto=None, cls_name='Object')
    FUNCTION_PROTO = JSObject(proto=OBJECT_PROTO, cls_name='Function')
    FUNCTION_PROTO._callable = True
    FUNCTION_PROTO.fn = lambda t, a: UNDEFINED
    ARRAY_PROTO = JSArray(items=[], proto=OBJECT_PROTO)
    STRING_PROTO = JSObject(proto=OBJECT_PROTO, cls_name='String')
    NUMBER_PROTO = JSObject(proto=OBJECT_PROTO, cls_name='Number')
    BOOLEAN_PROTO = JSObject(proto=OBJECT_PROTO, cls_name='Boolean')
    ERROR_PROTO = JSObject(proto=OBJECT_PROTO, cls_name='Error')
    ERROR_PROTO.define_property('name', 'Error', writable=True, enumerable=False, configurable=True)
    ERROR_PROTO.define_property('message', '', writable=True, enumerable=False, configurable=True)

    GLOBAL_OBJ = JSObject(proto=OBJECT_PROTO, cls_name='Object')
    GLOBAL_ENV = Env(is_function_scope=True)
    GLOBAL_ENV.vars['this'] = GLOBAL_OBJ

    # Object prototype methods
    def proto_toString(this, args):
        if this is UNDEFINED: return '[object Undefined]'
        if this is None: return '[object Null]'
        if isinstance(this, JSArray): return '[object Array]'
        if isinstance(this, JSObject):
            return f'[object {this.cls_name}]'
        if isinstance(this, str): return '[object String]'
        if isinstance(this, bool): return '[object Boolean]'
        if isinstance(this, (int, float)): return '[object Number]'
        return '[object Object]'
    define_method(OBJECT_PROTO, 'toString', proto_toString, 0)
    define_method(OBJECT_PROTO, 'valueOf', lambda this, args: this, 0)
    define_method(OBJECT_PROTO, 'hasOwnProperty', lambda this, args: isinstance(this, JSObject) and this.own_has(js_tostring(args[0] if args else UNDEFINED)), 1)
    define_method(OBJECT_PROTO, 'isPrototypeOf', lambda this, args: _is_prototype_of(this, args[0] if args else UNDEFINED), 1)
    define_method(OBJECT_PROTO, 'propertyIsEnumerable', lambda this, args: isinstance(this, JSObject) and js_tostring(args[0] if args else UNDEFINED) in this.own_enumerable_keys(), 1)

