        if idx[0] < len(items):
            o.set('value', items[idx[0]])
            o.set('done', False)
            idx[0] += 1
        else:
            o.set('value', UNDEFINED)
            o.set('done', True)
        return o
    it.define_property('next', native('next', nxt, 0), writable=True, enumerable=False, configurable=True)
    it.define_property('@@iterator', native('@@iterator', lambda t,a: it, 0), writable=True, enumerable=False, configurable=True)
    return it

