def setup_number_proto():
    p = NUMBER_PROTO
    def this_num(t):
        if isinstance(t, (int, float)) and not isinstance(t, bool): return float(t)
        if isinstance(t, JSObject) and t.cls_name == 'Number':
            return float(t._internal.get('primitive', 0))
        return js_tonumber(t)
    def to_fixed(t, a):
        n = this_num(t)
        digits = int(js_tonumber(a[0])) if a else 0
        if n != n: return 'NaN'
        if n == float('inf'): return 'Infinity'
        if n == float('-inf'): return '-Infinity'
        return f"{n:.{digits}f}"
    def to_string_n(t, a):
        n = this_num(t)
        if a and a[0] is not UNDEFINED:
            base = int(js_tonumber(a[0]))
            if base == 10 or n != n: return num_to_string(n)
            if n == float('inf'): return 'Infinity'
            if n == float('-inf'): return '-Infinity'
            if n == 0: return '0'
            if n.is_integer():
                i = int(n); neg = i < 0; i = abs(i)
                digs = '0123456789abcdefghijklmnopqrstuvwxyz'
                s = ''
                while i > 0:
                    s = digs[i % base] + s
                    i //= base
                return ('-' if neg else '') + s
            return num_to_string(n)
        return num_to_string(n)
    def to_precision(t, a):
        n = this_num(t)
        if not a or a[0] is UNDEFINED: return num_to_string(n)
        prec = int(js_tonumber(a[0]))
        if n != n: return 'NaN'
        if n == 0: return '0.' + '0'*(prec-1) if prec > 1 else '0'
        try: return f"{n:.{prec}g}"
        except: return num_to_string(n)
    def to_exp(t, a):
        n = this_num(t)
        digits = int(js_tonumber(a[0])) if a and a[0] is not UNDEFINED else 6
        s = f"{n:.{digits}e}"
        # Format like JS: 1.234e+5
        m, e = s.split('e')
        ei = int(e)
        sign = '+' if ei >= 0 else '-'
        return f"{m}e{sign}{abs(ei)}"
    define_method(p, 'toFixed', to_fixed, 1)
    define_method(p, 'toString', to_string_n, 1)
    define_method(p, 'toLocaleString', to_string_n, 0)
    define_method(p, 'toPrecision', to_precision, 1)
    define_method(p, 'toExponential', to_exp, 1)
    define_method(p, 'valueOf', lambda t,a: this_num(t), 0)

