def _parse_int(s, radix=10):
    s = s.strip()
    if not s: return float('nan')
    sign = 1
    if s[0] == '-': sign = -1; s = s[1:]
    elif s[0] == '+': s = s[1:]
    if (radix == 0 or radix == 16) and s[:2] in ('0x', '0X'):
        s = s[2:]; radix = 16
    if radix == 0: radix = 10
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'[:radix]
    val = ''
    for c in s:
        if c.lower() in digits: val += c
        else: break
    if not val: return float('nan')
    try: return float(sign * int(val, radix))
    except: return float('nan')

def _parse_float(s):
    s = s.strip()
    if not s: return float('nan')
    if s.startswith('Infinity') or s.startswith('+Infinity'): return float('inf')
    if s.startswith('-Infinity'): return float('-inf')
    # Find longest valid float prefix
    m = re.match(r'^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?', s)
    if not m: return float('nan')
    try: return float(m.group(0))
    except: return float('nan')

