def py_to_js(v):
    if v is None: return None
    if isinstance(v, bool): return v
    if isinstance(v, (int, float)): return float(v)
    if isinstance(v, str): return v
    if isinstance(v, list):
        return JSArray(items=[py_to_js(x) for x in v], proto=ARRAY_PROTO)
    if isinstance(v, dict):
        o = JSObject(proto=OBJECT_PROTO)
        for k, val in v.items():
            o.set(k, py_to_js(val))
        return o
    return UNDEFINED

def json_stringify(v, replacer=UNDEFINED, indent='', cur_indent=''):
    # Call toJSON if available
    if isinstance(v, JSObject):
        tj = v.get('toJSON')
        if isinstance(tj, (JSFunction, JSNativeFunction, JSBoundFunction)):
            v = call_function(tj, v, [''])
    if v is UNDEFINED: return None
    if v is None: return 'null'
    if isinstance(v, bool): return 'true' if v else 'false'
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        if v != v or v in (float('inf'), float('-inf')): return 'null'
        return num_to_string(float(v))
    if isinstance(v, str): return _json_str(v)
    if isinstance(v, BigInt):
        raise JSException(make_error('TypeError', 'Do not know how to serialize a BigInt'))
    if isinstance(v, (JSFunction, JSNativeFunction, JSBoundFunction)): return None
    if isinstance(v, JSArray):
        if not v.items: return '[]'
        new_indent = cur_indent + indent
        parts = []
        for x in v.items:
            s = json_stringify(x, replacer, indent, new_indent)
            if s is None: s = 'null'
            parts.append(s)
        if indent:
            return '[\n' + new_indent + (',\n' + new_indent).join(parts) + '\n' + cur_indent + ']'
        return '[' + ','.join(parts) + ']'
    if isinstance(v, JSObject):
        parts = []
        new_indent = cur_indent + indent
        for k in v.own_enumerable_keys():
            val = v.get_own_value(k)
            s = json_stringify(val, replacer, indent, new_indent)
            if s is None: continue
            sep = ': ' if indent else ':'
            parts.append(_json_str(k) + sep + s)
        if not parts: return '{}'
        if indent:
            return '{\n' + new_indent + (',\n' + new_indent).join(parts) + '\n' + cur_indent + '}'
        return '{' + ','.join(parts) + '}'
    return None

def _json_str(s):
    out = ['"']
    for c in s:
        if c == '"': out.append('\\"')
        elif c == '\\': out.append('\\\\')
        elif c == '\n': out.append('\\n')
        elif c == '\t': out.append('\\t')
        elif c == '\r': out.append('\\r')
        elif c == '\b': out.append('\\b')
        elif c == '\f': out.append('\\f')
        elif ord(c) < 0x20:
            out.append(f'\\u{ord(c):04x}')
        else:
            out.append(c)
    out.append('"')
    return ''.join(out)

