    def date_ctor(t, a):
        import time
        obj = JSObject(proto=OBJECT_PROTO, cls_name='Date')
        if not a:
            obj._internal['time'] = time.time() * 1000
        elif len(a) == 1:
            v = a[0]
            if isinstance(v, (int, float)):
                obj._internal['time'] = float(v)
            elif isinstance(v, str):
                # Parse ISO-8601
                try:
                    import datetime
                    if v.endswith('Z'):
                        dt = datetime.datetime.strptime(v, '%Y-%m-%dT%H:%M:%S.%fZ')
                        obj._internal['time'] = dt.timestamp() * 1000
                    else:
                        obj._internal['time'] = 0
                except: obj._internal['time'] = 0
        return obj
    ctor = JSNativeFunction('Date', date_ctor, 7, proto=FUNCTION_PROTO, construct=True)
    ctor.define_property('prototype', OBJECT_PROTO, writable=False, enumerable=False, configurable=False)
    def now(t, a):
        import time; return float(time.time() * 1000)
    define_method(ctor, 'now', now, 0)
    GLOBAL_OBJ.define_property('Date', ctor, True, False, True)
    GLOBAL_ENV.define('Date', ctor)

