# Need to implement generators. Let me add basic support
# Actually, let me just skip generators and convert them to arrays for simple cases
# Or better - add minimal generator support
python3 << 'EOF'
with open('src/qjs.py') as f:
    src = f.read()

# Parse yield as expression
# yield is already handled as unary? No. Let me add it as a primary expr.
old_primary_fn = '''    def parse_unary(self):
        t = self.peek()
        if t.type in ('!', '-', '+', '~', 'typeof', 'void', 'delete'):
            self.next()
            arg = self.parse_unary()
            return Node('Unary', op=t.type, arg=arg, prefix=True)
        if t.type in ('++', '--'):
            self.next()
            arg = self.parse_unary()
            return Node('Update', op=t.type, arg=arg, prefix=True)
        if t.type == 'await':
            self.next()
            arg = self.parse_unary()
            return Node('Await', arg=arg)
        return self.parse_postfix()'''
new_primary = '''    def parse_unary(self):
        t = self.peek()
        if t.type in ('!', '-', '+', '~', 'typeof', 'void', 'delete'):
            self.next()
            arg = self.parse_unary()
            return Node('Unary', op=t.type, arg=arg, prefix=True)
        if t.type in ('++', '--'):
            self.next()
            arg = self.parse_unary()
            return Node('Update', op=t.type, arg=arg, prefix=True)
        if t.type == 'await':
            self.next()
            arg = self.parse_unary()
            return Node('Await', arg=arg)
        if t.type == 'yield':
            self.next()
            delegate = False
            if self.peek().type == '*':
                self.next(); delegate = True
            # yield can take no argument
            if self.peek().type in (';', ',', ')', ']', '}', 'EOF') or self.peek().after_nl:
                return Node('Yield', arg=None, delegate=delegate)
            arg = self.parse_assignment()
            return Node('Yield', arg=arg, delegate=delegate)
        return self.parse_postfix()'''
src = src.replace(old_primary_fn, new_primary)

with open('src/qjs.py', 'w') as f:
    f.write(src)
