# Binary tree
cat > /tmp/tree.js <<'EOF'
class Node {
    constructor(v) { this.v = v; this.l = null; this.r = null; }
}
function insert(root, v) {
    if (!root) return new Node(v);
    if (v < root.v) root.l = insert(root.l, v);
    else root.r = insert(root.r, v);
    return root;
}
function inorder(node, arr) {
    if (!node) return;
    inorder(node.l, arr);
    arr.push(node.v);
    inorder(node.r, arr);
}
let tree = null;
for (const v of [5, 3, 7, 1, 4, 6, 8]) tree = insert(tree, v);
const sorted = [];
inorder(tree, sorted);
console.log(sorted);
EOF
