# Higher-order functions
cat > /tmp/hof.js <<'EOF'
const pipe = (...fns) => x => fns.reduce((v, f) => f(v), x);
const double = x => x * 2;
const add5 = x => x + 5;
const square = x => x * x;
const f = pipe(double, add5, square);
console.log(f(3));  // (3*2+5)^2 = 121

const memoize = fn => {
    const cache = {};
    return x => {
        if (x in cache) return cache[x];
        return cache[x] = fn(x);
    };
};
const fastFib = memoize(n => n < 2 ? n : fastFib(n-1) + fastFib(n-2));
console.log(fastFib(30));
EOF
