console.log(arr.map(x => x * x).reduce((a, b) => a + b, 0));

// Objects
const obj = {name: 'test', value: 42};
console.log(JSON.stringify(obj));
console.log(Object.keys(obj));

// Classes
class Shape {
    constructor(name) { this.name = name; }
    describe() { return `${this.name}`; }
}
class Circle extends Shape {
    constructor(r) { super('Circle'); this.r = r; }
    describe() { return `${super.describe()} with radius ${this.r}`; }
    area() { return Math.PI * this.r ** 2; }
}
const c = new Circle(5);
console.log(c.describe());
console.log(c.area().toFixed(2));

// Iterators
function* range(start, end, step = 1) {
    for (let i = start; i < end; i += step) yield i;
}
console.log([...range(1, 10, 2)]);

// Async
async function delay() { return 'done'; }
delay().then(v => console.log('async:', v));

// Destructuring
const [first, ...rest] = [1, 2, 3, 4];
console.log(first, rest);

const { name, value } = obj;
console.log(name, value);

// Error handling
try {
    throw new Error('test error');
} catch (e) {
    console.log('caught:', e.message);
}

// Regex
const re = /(\w+)@(\w+)\.(\w+)/;
const match = 'user@example.com'.match(re);
console.log(match[1], match[2], match[3]);

// Map and Set
const m = new Map([['a', 1], ['b', 2]]);
console.log(m.size, m.get('a'));

const s = new Set([1, 2, 2, 3, 3, 3]);
console.log(s.size);

console.log('--- End ---');
